#!/usr/bin/env bash
# Add WeightInfo traits to turbine, sealevel, ibc, poh pallets
# and wire them into the runtime config
set -e

cd /opt/verdis-chain-rust

# ============ TURBINE ============
cat > pallets/turbine/src/weights.rs << 'RUST'
//! Autogenerated weights for pallet_turbine
use frame_support::{traits::Get, weights::{Weight, constants::RocksDbWeight}};
use core::marker::PhantomData;

/// Weight functions for pallet_turbine.
pub trait WeightInfo {
    fn register_shard() -> Weight;
    fn rebuild_tree(v: u32) -> Weight;
    fn mark_block_propagated() -> Weight;
}

/// Default weights using reasonable estimates.
pub struct SubstrateWeight<T>(PhantomData<T>);
impl<T: frame_system::Config> WeightInfo for SubstrateWeight<T> {
    fn register_shard() -> Weight {
        // Storage: read shard count, write shard entry
        Weight::from_parts(50_000, 0)
            .saturating_add(T::DbWeight::get().reads(1))
            .saturating_add(T::DbWeight::get().writes(1))
    }
    fn rebuild_tree(v: u32) -> Weight {
        // O(n) tree rebuild over validators
        Weight::from_parts(20_000, 0)
            .saturating_add(Weight::from_parts(2_000, 0).saturating_mul(v.into()))
            .saturating_add(T::DbWeight::get().reads(1))
            .saturating_add(T::DbWeight::get().writes(1))
    }
    fn mark_block_propagated() -> Weight {
        // Simple storage write
        Weight::from_parts(20_000, 0)
            .saturating_add(T::DbWeight::get().reads(1))
            .saturating_add(T::DbWeight::get().writes(1))
    }
}
RUST

# Add weights module to turbine lib.rs
python3 << 'PYEOF'
with open('pallets/turbine/src/lib.rs', 'r') as f:
    content = f.read()

# Add pub mod weights if not exists
if 'pub mod weights' not in content:
    # Add after the first use statement
    content = content.replace(
        '#[cfg_attr(not(feature = "std"), no_std)]',
        '#[cfg_attr(not(feature = "std"), no_std)]\npub mod weights;\nuse weights::WeightInfo;',
        1
    )

# Add type WeightInfo to Config trait
if 'type WeightInfo' not in content.split('pub enum Event')[0] if 'pub enum Event' in content else True:
    # Find the Config trait and add WeightInfo
    content = content.replace(
        'pub trait Config: frame_system::Config {',
        'pub trait Config: frame_system::Config {\n\t\ttype WeightInfo: WeightInfo;',
        1
    )

# Replace weight(0) with WeightInfo calls
content = content.replace(
    '#[pallet::weight(0)]\n        pub fn register_shard(',
    '#[pallet::weight(T::WeightInfo::register_shard())]\n        pub fn register_shard('
)
content = content.replace(
    '#[pallet::weight(0)]\n        pub fn rebuild_tree(',
    '#[pallet::weight(T::WeightInfo::rebuild_tree(validator_count))]\n        pub fn rebuild_tree('
)
content = content.replace(
    '#[pallet::weight(0)]\n        pub fn mark_block_propagated(',
    '#[pallet::weight(T::WeightInfo::mark_block_propagated())]\n        pub fn mark_block_propagated('
)

with open('pallets/turbine/src/lib.rs', 'w') as f:
    f.write(content)
print("TURBINE: WeightInfo added")
PYEOF

