# ============ POH ============
# PoH already has WeightInfo trait defined, just need to add to Config and runtime
python3 << 'PYEOF'
with open('pallets/poh/src/lib.rs', 'r') as f:
    content = f.read()

# Check if WeightInfo is already in Config
config_section = content.split('pub trait Config: frame_system::Config {')
if len(config_section) > 1:
    config_body = config_section[1].split('}')[0]
    if 'type WeightInfo' not in config_body:
        content = content.replace(
            'pub trait Config: frame_system::Config {',
            'pub trait Config: frame_system::Config {\n\t\ttype WeightInfo: WeightInfo;',
            1
        )
        print("POH: WeightInfo added to Config")
    else:
        print("POH: WeightInfo already in Config")
else:
    print("POH: Config trait not found in expected format")

# Replace hardcoded weights with WeightInfo calls
content = content.replace(
    '#[pallet::weight(Weight::from_parts(10_000, 0))]\n        pub fn record_block(',
    '#[pallet::weight(T::WeightInfo::record_block())]\n        pub fn record_block('
)
content = content.replace(
    '#[pallet::weight(Weight::from_parts(10_000, 0))]\n        pub fn set_config(',
    '#[pallet::weight(T::WeightInfo::set_config())]\n        pub fn set_config('
)
content = content.replace(
    '#[pallet::weight(Weight::from_parts(10_000, 0))]\n        pub fn tick_extrinsic(',
    '#[pallet::weight(T::WeightInfo::tick_extrinsic())]\n        pub fn tick_extrinsic('
)

with open('pallets/poh/src/lib.rs', 'w') as f:
    f.write(content)
print("POH: WeightInfo weights applied")
PYEOF

# ============ RUNTIME CONFIG ============
python3 << 'PYEOF'
with open('runtime/src/lib.rs', 'r') as f:
    content = f.read()

# Add WeightInfo to runtime config for each pallet
# Find the Config impl blocks and add WeightInfo

# Turbine
if 'pallet_turbine::SubstrateWeight<Runtime>' not in content:
    # Find the turbine Config impl
    import re
    turbine_match = re.search(r'(impl pallet_turbine::Config for Runtime \{[^}]+)', content)
    if turbine_match:
        old = turbine_match.group(1)
        if 'type WeightInfo' not in old:
            new = old.rstrip() + '\n    type WeightInfo = pallet_turbine::SubstrateWeight<Runtime>;'
            content = content.replace(old, new)
            print("RUNTIME: Turbine WeightInfo added")

# Sealevel
if 'pallet_sealevel::SubstrateWeight<Runtime>' not in content:
    sealevel_match = re.search(r'(impl pallet_sealevel::Config for Runtime \{[^}]+)', content)
    if sealevel_match:
        old = sealevel_match.group(1)
        if 'type WeightInfo' not in old:
            new = old.rstrip() + '\n    type WeightInfo = pallet_sealevel::SubstrateWeight<Runtime>;'
            content = content.replace(old, new)
            print("RUNTIME: Sealevel WeightInfo added")

# IBC
if 'pallet_ibc::SubstrateWeight<Runtime>' not in content:
    ibc_match = re.search(r'(impl pallet_ibc::Config for Runtime \{[^}]+)', content)
    if ibc_match:
        old = ibc_match.group(1)
        if 'type WeightInfo' not in old:
            new = old.rstrip() + '\n    type WeightInfo = pallet_ibc::SubstrateWeight<Runtime>;'
            content = content.replace(old, new)
            print("RUNTIME: IBC WeightInfo added")

# PoH
if 'pallet_poh::SubstrateWeight<Runtime>' not in content:
    poh_match = re.search(r'(impl pallet_poh::Config for Runtime \{[^}]+)', content)
    if poh_match:
        old = poh_match.group(1)
        if 'type WeightInfo' not in old:
            new = old.rstrip() + '\n    type WeightInfo = pallet_poh::SubstrateWeight<Runtime>;'
            content = content.replace(old, new)
            print("RUNTIME: PoH WeightInfo added")

with open('runtime/src/lib.rs', 'w') as f:
    f.write(content)
print("RUNTIME: All WeightInfo configs updated")
PYEOF

echo ""
echo "=== WEIGHTINFO INTEGRATION COMPLETE ==="
echo "Pallets modified: turbine, sealevel, ibc, poh"
echo "Each has: weights.rs, WeightInfo trait, Config type, runtime config"
